// Three.js 3D Scene Setup for Jelly Villa
import * as THREE from 'three';

class JellyVistaScene {
    constructor() {
        this.container = document.getElementById('canvas-container');
        this.scene = new THREE.Scene();

        // Background gradient (water depth)
        this.backgroundGradient = [0x0d1e28, 0x1a475c];

        this.camera = new THREE.PerspectiveCamera(75, window.innerWidth / window.innerHeight, 0.1, 1000);
        this.renderer = new THREE.WebGLRenderer({ antialias: true, alpha: true });

        // Renderer setup
        this.renderer.setSize(window.innerWidth, window.innerHeight);
        this.renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
        this.renderer.toneMapping = THREE.ACESFilmicToneMapping;
        this.renderer.toneMappingExposure = 1.2;

        this.container.appendChild(this.renderer.domElement);

        // Lighting setup (ambient underwater environment)
        this.initLighting();

        // Scene objects
        this.jellyfishGroup = new THREE.Group();
        this.bubbles = [];
        this.particles = [];
        this.waterVolume = null;

        this.scene.add(this.jellyfishGroup);

        // Animation loop
        this.clock = new THREE.Clock();
        this.initInteractions();
    }

    initLighting() {
        // Ambient blue underwater light (cool, dim)
        const ambientLight = new THREE.AmbientLight(0x1a2b4c, 0.5);
        this.scene.add(ambientLight);

        // Main spotlight from above surface (simulating sunlight filtering through water)
        const sunLight = new THREE.DirectionalLight(0xaaccff, 1.2);
        sunLight.position.set(5, 20, -10);
        sunLight.castShadow = true;
        this.scene.add(sunLight);

        // Secondary warm glow (deep water bioluminescence)
        const glowLight = new THREE.PointLight(0x4455aa, 0.8, 20);
        glowLight.position.set(-10, -5, 10);
        this.scene.add(glowLight);

        // Rim light for jellyfish silhouette edges (cyan/magenta rim)
        const rimLeft = new THREE.SpotLight(0x00aaff, 0.4, 30, Math.PI / 6, 0.5, 1);
        rimLeft.position.set(-20, 0, 10);
        this.scene.add(rimLeft);

        const rimRight = new THREE.SpotLight(0xff00aa, 0.4, 30, Math.PI / 6, 0.5, 1);
        rimRight.position.set(20, 0, 10);
        this.scene.add(rimRight);

        // Volumetric fog (depth atmosphere)
        const fog = new THREE.FogExp2(0x0d1e28, 0.02);
        this.scene.fog = fog;
    }

    createJellyfish(size, position, color, type = 'standard') {
        // Jelly body (translucent sphere with soft glow)
        const geometry = new THREE.SphereGeometry(1 * size, 40, 40);

        // Translucent jelly material with internal glow
        const material = new THREE.MeshPhysicalMaterial({
            color: color,
            roughness: 0.3,
            metalness: 0.1,
            transmission: 0.6,
            thickness: 0.8,
            transparent: true,
            opacity: 0.4,
            side: THREE.DoubleSide,
            emissive: color,
            emissiveIntensity: 0.3,
        });

        const jellyBody = new THREE.Mesh(geometry, material);
        jellyBody.position.copy(position);

        // Add pulsating effect
        this.jellyfishGroup.add(jellyBody);

        // Create flowing tentacles (multiple curves)
        const tentaclesCount = 12 + Math.floor(Math.random() * 8);
        for(let i = 0; i < tentaclesCount; i++) {
            const angleOffset = (Math.PI / tentaclesCount) * i + position.x * 0.3;

            // Curved tentacle path using Bezier curves
            const pathPoints = [];
            let prevPoint = new THREE.Vector3(0, size*1.5 + (i % 2) * 0.5 - (Math.sin(i * 0.8) * 0.5), 0);

            for(let j = 0; j < 6; j++) {
                const t = j / 6;
                prevPoint.y -= size * 1.2 * (t + (j % 3 === 0 ? Math.sin(j) : 0)); // Sway motion
                pathPoints.push(prevPoint);
            }

            // Create tentacle mesh from path
            const curve = new THREE.CatmullRomCurve3(pathPoints, true);
            const tubeGeometry = new THREE.TubeGeometry(curve, 20, size * 0.15, 8, false);

            const tubeMaterial = new THREE.MeshPhysicalMaterial({
                color: 0x2b4c6e,
                transparent: true,
                opacity: 0.2 + Math.random() * 0.1,
                roughness: 0.5,
                side: THREE.DoubleSide,
            });

            const tentacle = new THREE.Mesh(tubeGeometry, tubeMaterial);
            jellyBody.add(tentacle);
        }

        return { mesh: jellyBody, originalColor: color };
    }

    createBubbles() {
        for(let i = 0; i < 50; i++) {
            // Random bubble size and position
            const radius = 0.1 + Math.random() * 0.6;
            const geometry = new THREE.SphereGeometry(radius, 8, 8);

            // Translucent bubble material (water-like)
            const material = new THREE.MeshPhysicalMaterial({
                color: 0xaaccff,
                transparent: true,
                opacity: 0.15 + Math.random() * 0.1,
                roughness: 0.2,
                metalness: 0.3,
            });

            const bubble = new THREE.Mesh(geometry, material);

            // Random starting position (below camera, rising)
            bubble.position.set(
                (Math.random() - 0.5) * 40,
                -10 + Math.random() * 20,
                (Math.random() - 0.5) * 20
            );

            // Track for animation
            const bubbleData = {
                mesh: bubble,
                speed: 0.2 + Math.random() * 0.3,
                wobbleOffset: Math.random() * Math.PI * 2,
            };

            this.bubbles.push(bubbleData);
        }

        // Add to scene
        for(let b of this.bubbles) {
            this.scene.add(b.mesh);
        }
    }

    createFloatingParticles() {
        const particleCount = 100;

        for(let i = 0; i < particleCount; i++) {
            // Small floating specks (dust/luminescence)
            const geometry = new THREE.SphereGeometry(0.05, 6, 6);

            const material = new THREE.MeshBasicMaterial({
                color: Math.random() > 0.7 ? 0x6688cc : 0xaaccff,
                transparent: true,
                opacity: 0.3 + Math.random() * 0.2,
            });

            const particle = new THREE.Mesh(geometry, material);

            // Random distribution in wide volume
            particle.position.set(
                (Math.random() - 0.5) * 60,
                (Math.random() - 0.5) * 40,
                (Math.random() - 0.5) * 30
            );

            this.particles.push(particle);
        }

        // Add to scene
        for(let p of this.particles) {
            this.scene.add(p);
        }
    }

    initInteractions() {
        // Mouse movement affects camera
        const mouse = new THREE.Vector2();

        document.addEventListener('mousemove', (event) => {
            // Subtle parallax effect on jellyfish group
            const time = this.clock.getElapsedTime() * 0.1;
            this.jellyfishGroup.position.x = 
                -mouse.x * 0.05 + Math.sin(time) * 2;
            this.jellyfishGroup.position.y = 
                -mouse.y * 0.03 + Math.cos(time * 0.8) * 1.5;
        });

        // Click to expand view or interact with objects
        this.container.addEventListener('click', () => {
            console.log("3D Scene Interaction Triggered");

            // Create ripple effect on click
            const ripple = new THREE.PointLight(0x6688aa, 1, 15);
            ripple.position.copy(this.camera.position).add(new THREE.Vector3(Math.random()-0.5, Math.random()-0.5, Math.random()-0.5));
            this.scene.add(ripple);

            setTimeout(() => {
                this.scene.remove(ripple);
            }, 1000);
        });

        // Window resize handling
        window.addEventListener('resize', () => {
            this.camera.aspect = window.innerWidth / window.innerHeight;
            this.camera.updateProjectionMatrix();
            this.renderer.setSize(window.innerWidth, window.innerHeight);
        });
    }

    animate() {
        requestAnimationFrame(() => this.animate());

        const time = this.clock.getElapsedTime();

        // Animate jellyfish (gentle bobbing)
        for(let i = 0; i < 15; i++) {
            const mesh = this.jellyfishGroup.children[i];

            // Subtle vertical floating motion
            mesh.position.y += Math.sin(time + i * 0.3) * 0.02;
            mesh.rotation.z += Math.sin(time * 0.7 + i) * 0.01;
        }

        // Animate bubbles (rising with wobble)
        for(let b of this.bubbles) {
            b.mesh.position.y += b.speed;

            // Horizontal wobble as they rise
            b.mesh.position.x = Math.sin(time + b.wobbleOffset) * 0.5;
            b.mesh.rotation.z = time * 0.1 + b.wobbleOffset;

            // Reset when above camera
            if(b.mesh.position.y > this.camera.position.y + 20) {
                b.mesh.position.set(
                    (Math.random() - 0.5) * 40,
                    -10 + Math.random() * 20,
                    (Math.random() - 0.5) * 20
                );
                b.wobbleOffset = Math.random() * Math.PI * 2;
            }
        }

        // Animate particles (slow floating)
        for(let i = this.particles.length - 1; i >= 0; i--) {
            const p = this.particles[i];

            // Very slow random motion
            if(Math.random() < 0.02) {
                p.position.y += Math.sin(time + i * 0.5) * 0.03;
            }

            // Reset when too high
            if(p.position.y > -5 && Math.random() < 0.01) {
                this.scene.remove(p);
                this.particles.splice(i, 1);
            }
        }

        // Camera slow drift (breathing effect)
        const cameraOffset = 3;
        this.camera.position.y = cameraOffset + Math.sin(time * 0.5) * 2;
        this.camera.position.x = -Math.cos(time * 0.3) * 1;

        // Update camera lookAt (slight rotation toward center with parallax)
        const lookX = this.jellyfishGroup.position.x - this.camera.position.x * 0.1;
        const lookY = this.jellyfishGroup.position.y - this.camera.position.y * 0.1;
        this.camera.lookAt(lookX, lookY, 0);

        // Render
        this.renderer.render(this.scene, this.camera);
    }
}

