document.addEventListener('DOMContentLoaded', () => {
    const scene = new JellyVistaScene();

    // Create jellyfish population (12-15 large ones)
    for(let i = 0; i < 18; i++) {
        const jellyfishGroup = scene.jellyfishGroup;

        // Distribute in a loose cluster/reef formation
        const angle = (i / 18) * Math.PI * 2 - Math.PI;
        const radius = 3 + Math.sin(i * 0.5) * 3;

        const position = new THREE.Vector3(
            Math.cos(angle) * radius,
            -5 + i * 0.3, // Staggered vertical positions
            Math.sin(angle) * radius
        );

        // Varying sizes and colors
        const size = 1.2;

        // Gradient color palette (purple to blue-green to pink)
        const hue = 250 + (i / 18) * 60 - Math.sin(i * 0.3) * 30; // Purple-blue range
        const color = new THREE.Color(`hsl(${hue}, 70%, ${40 + i % 3}%)`);

        scene.createJellyfish(size, position, color, 'standard');
    }

    // Initialize special effects
    scene.createBubbles();
    scene.createFloatingParticles();

    // Start animation loop
    scene.animate();

    console.log("Jelly Villa 3D Scene Initialized");
    console.log(`Loaded ${18} jellyfish + bubbles + particles`);
