class JellyVistaEvents {
    constructor() {
        this.initEventListeners();
        this.initScrollHandlers();
        this.initResizeHandlers();
    }

    initEventListeners() {
        // 3D scene interaction (click creates ripples)
        const container = document.querySelector('#canvas-container');

        if(container) {
            container.addEventListener('click', () => {
                console.log("3D Scene: Ripple Effect Triggered");

                // Create temporary light effect
                const time = new Date().getTime() * 0.01;
                const rippleLight = document.createElement('div');

                rippleLight.style.cssText = `
                    position: fixed;
                    left: ${event.clientX}px;
                    top: ${event.clientY}px;
                    width: 10px; height: 10px;
                    background: radial-gradient(circle, var(--color-accent-cyan) 0%, transparent 70%);
                    border-radius: 50%;
                    transform: translate(-50%, -50%) scale(1);
                    pointer-events: none;
                `;

                document.body.appendChild(rippleLight);

                // Animate ripple expanding and fading
                const duration = 800;
                const startTime = Date.now();

                function animate() {
                    if(Date.now() - startTime > duration) return;

                    const elapsed = Date.now() - startTime;
                    const scale = 1 + (elapsed / duration);

                    rippleLight.style.transform = `translate(-50%, -50%) scale(${scale})`;
                    rippleLight.style.opacity = 1 - (elapsed / duration);

                    requestAnimationFrame(animate);
                }

                animate();

                // Cleanup after animation
                setTimeout(() => {
                    document.body.removeChild(rippleLight);
                }, duration + 200);
            });
        }

        // Keyboard accessibility (tab navigation)
        window.addEventListener('keydown', (e) => {
            console.log(`Key pressed: ${e.key}`);

            if(e.key === 'Escape') {
                const mobileMenu = document.getElementById('mobile-menu');
                if(mobileMenu && !mobileMenu.classList.contains('-translate-y-full')) {
                    toggleMenu(); // Close menu on ESC
                }
            }

            if(e.key.toLowerCase() === '?' && !e.shiftKey) {
