                    display: flex;
                    align-items: center;
                    justify-content: center;
                `;

                const helpContent = document.createElement('div');
                helpContent.className = 'glass-panel p-8 rounded-2xl max-w-lg text-center';
                helpContent.innerHTML = `
                    <h3 class="text-2xl font-bold gradient-text mb-4">Keyboard Shortcuts</h3>
                    <p class="mb-2"><span class="font-mono bg-white/10 px-2 py-1 rounded">TAB / ENTER</span> - Navigate interactive buttons</p>
                    <p class="mb-2"><span class="font-mono bg-white/10 px-2 py-1 rounded">ESC</span> - Close menus</p>
                    <p><span class="font-mono bg-white/10 px-2 py-1 rounded">?</span> - Show this help overlay</p>
                `;

                document.body.appendChild(helpModal);
                document.body.appendChild(helpContent);

                // Close after 3 seconds or on click
                setTimeout(() => {
                    if(document.getElementById('help-overlay')) {
                        const overlays = [helpModal, helpContent];
                        overlays.forEach(el => document.body.removeChild(el));
                        console.log("Help overlay removed");
                    }
                }, 3000);
            }
        });

        // Touch/swipe gestures for mobile
        let touchStartY = 0;

        if('ontouchstart' in window) {
            container.addEventListener('touchstart', (e) => {
                touchStartY = e.touches[0].clientY;
            }, { passive: true });

            container.addEventListener('touchend', (e) => {
                const touchEndY = e.changedTouches[0].clientY;

                if(touchStartY - touchEndY > 80) {
                    console.log("Swipe up gesture detected");

                    // Swipe up to expand view
                    gsap.to('.glass-panel', { duration: 0.8, y: -150 });
                }

                if(touchEndY - touchStartY > 80) {
                    console.log("Swipe down gesture detected");

                    // Swipe down to collapse/minimize
                    gsap.to('.glass-panel', { duration: 0.8, y: 0 });
                }
            }, { passive: true });
        }
    }

    initScrollHandlers() {
        let lastY = window.scrollY;

        window.addEventListener('scroll', () => {
            const currentY = window.scrollY;

            // Parallax effect on UI panels based on scroll
            if(currentY > 0 && lastY < 100) {
                const heroSection = document.getElementById('hero');

                gsap.to(heroSection.children, {
                    y: currentY * 0.3,
                    duration: 0.5,
                    ease: 'power2.out'
                });
            }

            lastY = currentY;
        }, { passive: true });
    }

    initResizeHandlers() {
        let resizeTimer;

        window.addEventListener('resize', () => {
            // Debounce resize events (wait 100ms before executing)
            clearTimeout(resizeTimer);

            resizeTimer = setTimeout(() => {
                console.log(`Window resized to: ${window.innerWidth}x${window.innerHeight}`);

                // Adjust 3D camera for different aspect ratios
